493:   const latest = samples[samples.length - 1];
494:   if (!latest.stable || latest.confidence < CONFIDENCE_FLOOR) {
495:     return samples.some((sample) => sample.stable && sample.confidence >= CONFIDENCE_FLOOR)
496:       ? 'Low confidence.'
497:       : 'Validating.';
498:   }
499:   return 'Sensing.';
500: }
