508: async function stageAtomic(filePath: string, body: string, fs: AtomicFileSystem): Promise<string> {
509:   const tmp = `${filePath}.${process.pid}.${randomBytes(6).toString('hex')}.tmp`;
510:   const handle = await fs.open(tmp, 'w', 0o600);
511:   try {
512:     await closeAfter(handle, async () => {
513:       await handle.writeFile(body);
514:       await handle.sync();
515:     });
516:   } catch (error) {
517:     await removeAtomicTemp(tmp, fs);
518:     throw error;
519:   }
520:   return tmp;
