529: async function closeAfter(handle: AtomicFileHandle, operation: () => Promise<void>): Promise<void> {
530:   let failed = false;
531:   let failure: unknown;
532:   try {
533:     await operation();
534:   } catch (error) {
535:     failed = true;
536:     failure = error;
537:   }
538:   try {
539:     await handle.close();
540:   } catch (error) {
541:     if (!failed) {
542:       failed = true;
543:       failure = error;
544:     }
545:   }
546:   if (failed) throw failure;
547: }
