570: function exclusive<T>(root: string, fn: () => Promise<T>): Promise<T> {
571:   const key = path.resolve(root);
572:   const previous = tails.get(key) ?? Promise.resolve();
573:   const run = previous.then(fn, fn);
574:   tails.set(key, run.then(() => undefined, () => undefined));
575:   return run;
576: }
