109:   // The floor stays at lastTUs rather than advancing with each reading: a payload whose samples
110:   // arrive out of order would otherwise lose an earlier-but-new reading. Ordering is restored
111:   // below, and a repeated timestamp keeps the first reading, as before.
112:   const collected: PulseSample[] = [];
113:   for (const raw of series) {
114:     const sample = toPulseSample(raw, anchor, lastTUs);
115:     if (sample) collected.push(sample);
116:   }
117:   // A stable sort keeps payload order among equal timestamps, so the first reading wins.
118:   collected.sort((left, right) => left.tUs - right.tUs);
119:   const fresh: PulseSample[] = [];
120:   for (const sample of collected) {
121:     const previous = fresh[fresh.length - 1];
