93:   [SDK_ERROR.timestampGap]: 'The camera stopped sending frames.',
94:   [SDK_ERROR.metricNotAuthorized]: 'This SmartSpectra key is not allowed to measure pulse.',
95:   [SDK_ERROR.sustainedLowFrameRate]: 'The camera frame rate stayed too low.',
96: };
97: 
98: /**
99:  * Every pulse reading in a decoded metrics payload that is newer than the last one stored.
100:  * Weak samples are kept: the raw trace keeps them and coverage is what falls.
101:  */
102: export function newPulseSamples(
103:   payload: unknown,
104:   anchor: SessionAnchor,
105:   lastTUs: number,
106: ): PulseSample[] {
107:   const series = pulseSeries(payload);
108:   if (!series) return [];
109:   // The floor stays at lastTUs rather than advancing with each reading: a payload whose samples
110:   // arrive out of order would otherwise lose an earlier-but-new reading. Ordering is restored
111:   // below, and a repeated timestamp keeps the first reading, as before.
112:   const collected: PulseSample[] = [];
113:   for (const raw of series) {
114:     const sample = toPulseSample(raw, anchor, lastTUs);
115:     if (sample) collected.push(sample);
116:   }
117:   // A stable sort keeps payload order among equal timestamps, so the first reading wins.
118:   collected.sort((left, right) => left.tUs - right.tUs);
119:   const fresh: PulseSample[] = [];
120:   for (const sample of collected) {
121:     const previous = fresh[fresh.length - 1];
122:     if (previous && previous.tUs === sample.tUs) continue;
123:     fresh.push(sample);
124:   }
125:   return fresh;
126: }
127: 
128: /** The newest pulse reading in a decoded metrics payload. Kept for callers that want only one. */
129: export function latestPulseSample(
130:   payload: unknown,
131:   anchor: SessionAnchor,
132:   lastTUs: number,
133: ): PulseSample | null {
134:   const fresh = newPulseSamples(payload, anchor, lastTUs);
135:   return fresh.length > 0 ? fresh[fresh.length - 1] : null;
136: }
137: 
138: export function toPulseSample(
139:   raw: unknown,
140:   anchor: SessionAnchor,
141:   lastTUs: number,
142: ): PulseSample | null {
143:   const parsed = readingSchema.safeParse(raw);
144:   if (!parsed.success) return null;
145:   if (parsed.data.value < MIN_PULSE_BPM || parsed.data.value > MAX_PULSE_BPM) return null;
146:   const timestamp = epochUs(parsed.data.timestamp);
147:   if (timestamp === null) return null;
148:   const tUs = anchor.monoUs + (timestamp - anchor.epochMs * 1000);
149:   if (!Number.isSafeInteger(tUs) || tUs < anchor.monoUs || tUs <= lastTUs) return null;
150:   return {
151:     tUs,
152:     bpm: parsed.data.value,
153:     confidence: parsed.data.confidence,
154:     stable: parsed.data.stable,
155:   };
156: }
157: 
158: export function validationMessage(
159:   code: number,
160:   timestampUs: number,
161:   hint: string,
162:   anchor: SessionAnchor,
163: ): ValidationMessage | null {
164:   const timestamp = epochUs(timestampUs);
165:   if (timestamp === null) return null;
166:   const tUs = anchor.monoUs + (timestamp - anchor.epochMs * 1000);
167:   if (!Number.isSafeInteger(tUs) || tUs < 0) return null;
168:   return validationMessageSchema.parse({ code, ts: tUs, hint: validationText(code, hint) });
169: }
170: 
171: export function validationText(code: number, hint: string): string {
172:   const trimmed = typeof hint === 'string' ? hint.trim() : '';
173:   if (trimmed.length > 0) return truncate(trimmed);
174:   return VALIDATION_COPY[code] ?? 'Measuring.';
175: }
176: 
177: export function sdkErrorMessage(code: number, detail: string): string {
178:   const copy = SDK_ERROR_COPY[code];
179:   if (copy) return copy;
180:   const trimmed = typeof detail === 'string' ? truncate(detail.trim()) : '';
181:   return trimmed.length > 0
182:     ? `${trimmed} (sensing code ${code})`
183:     : `Sensing stopped unexpectedly (code ${code}).`;
184: }
185: 
186: function pulseSeries(payload: unknown): unknown[] | null {
187:   if (typeof payload !== 'object' || payload === null) return null;
188:   const cardio = (payload as { cardio?: unknown }).cardio;
189:   if (typeof cardio !== 'object' || cardio === null) return null;
190:   const series = (cardio as { pulseRate?: unknown }).pulseRate;
191:   if (!Array.isArray(series) || series.length === 0) return null;
192:   return series;
193: }
194: 
195: /** protobufjs hands int64 back as a Long, so accept a number or anything with toNumber(). */
196: function epochUs(value: unknown): number | null {
197:   if (typeof value === 'number') return isEpochUs(value) ? value : null;
198:   if (typeof value === 'object' && value !== null) {
199:     const toNumber = (value as { toNumber?: unknown }).toNumber;
200:     if (typeof toNumber === 'function') {
201:       const converted = (toNumber as () => unknown).call(value);
202:       if (typeof converted === 'number' && isEpochUs(converted)) return converted;
203:     }
204:   }
205:   return null;
206: }
207: 
208: function isEpochUs(value: number): boolean {
209:   return Number.isSafeInteger(value) && value > 0;
210: }
211: 
212: function truncate(text: string): string {
213:   return text.length > MAX_TEXT_LENGTH ? `${text.slice(0, MAX_TEXT_LENGTH - 1)}…` : text;
214: }

