1: // What: routes window close, quit, and consent revocation through one stop function.
2: // Why: every route must drain the camera and close the header before the process or window exits.
3: // Removed: a trigger could forget to stop, or quit before the final sample write landed.
4: export interface ShutdownEvent {
5:   preventDefault(): void;
6: }
