8: export interface ShutdownDependencies {
9:   stop(): Promise<unknown>;
10:   hasActive(): boolean;
11:   quit(): void;
12: }
13: 
14: export interface ShutdownHooks {
15:   beginStart(): void;
16:   captureAllowed(): boolean;
17:   onWindowAllClosed(): void;
18:   onConsentRevoked(): void;
19:   onBeforeQuit(event: ShutdownEvent): void;
20: }
21: 
22: export function createShutdownHooks(deps: ShutdownDependencies): ShutdownHooks {
23:   let captureDesired = false;
24:   let quitting = false;
25:   let exitAllowed = false;
26:   const beginStop = (): Promise<unknown> => {
27:     captureDesired = false;
28:     return deps.stop().catch(() => undefined);
29:   };
30: 
31:   return {
32:     beginStart() {
33:       if (quitting) return;
34:       captureDesired = true;
35:       exitAllowed = false;
36:     },
37:     captureAllowed() {
38:       return captureDesired;
39:     },
40:     onWindowAllClosed() {
41:       void beginStop();
42:     },
43:     onConsentRevoked() {
44:       void beginStop();
45:     },
46:     onBeforeQuit(event) {
47:       if (exitAllowed) return;
48:       if (!deps.hasActive()) {
49:         exitAllowed = true;
50:         return;
51:       }
52:       event.preventDefault();
53:       if (quitting) return;
54:       quitting = true;
55:       void beginStop().finally(() => {
56:         exitAllowed = true;
57:         deps.quit();
58:       });
59:     },
60:   };
61: }

