3:   type SessionEndReason,
4:   type SessionEnded,
5:   type SessionMeta,
6: } from '../shared/contracts.js';
7: import type { SessionStopReason } from './session.js';
8: 
9: export interface SessionStopSeams {
10:   stopCapture(): Promise<SessionEndReason | undefined>;
11:   stopSession(reason: SessionStopReason): Promise<SessionMeta>;
12:   publish(event: SessionEnded): void;
13: }
14: 
15: export interface SessionStopper {
16:   beginSession(): void;
17:   stop(reason: SessionStopReason): Promise<SessionMeta>;
18:   active(): boolean;
19: }
20: 
21: const SESSION_ENDED_COPY: Record<SessionEndReason, string> = {
22:   storage: 'Sensing stopped because the pulse samples could not be saved. The session was closed.',
23:   limit: 'Sensing stopped at the 90-minute limit. The session was closed.',
24: };
25: 
26: // What: runs camera teardown, session finalization, and one automatic-ended publication as one operation.
27: // Why: concurrent user, SDK, storage, and limit stops must share one reason and one visible event.
28: // Removed: a second caller could finalize again or publish a different terminal reason.
29: export function createSessionStopper(seams: SessionStopSeams): SessionStopper {
30:   let inFlight: Promise<SessionMeta> | null = null;
31:   let pendingReason: SessionEndReason | undefined;
32:   // A finalized session whose automatic event still needs the page. A retry republishes this,
33:   // never finalizes again.
34:   let retained: { meta: SessionMeta; event: SessionEnded } | null = null;
35: 
36:   return {
37:     beginSession() {
38:       pendingReason = undefined;
39:       retained = null;
40:     },
41:     stop(reason) {
42:       if (inFlight) return inFlight;
43:       const run = (async () => {
44:         if (retained) {
45:           const { meta, event } = retained;
46:           seams.publish(event);
47:           retained = null;
48:           return meta;
49:         }
50:         const captureReason = await seams.stopCapture();
51:         const effectiveReason = captureReason ?? pendingReason ?? reason;
52:         if (effectiveReason === 'storage' || effectiveReason === 'limit') {
53:           pendingReason = effectiveReason;
54:         }
55:         const meta = await seams.stopSession(effectiveReason);
56:         pendingReason = undefined;
57:         if (effectiveReason === 'storage' || effectiveReason === 'limit') {
58:           const event = sessionEndedSchema.parse({
59:             sessionId: meta.id,
60:             reason: effectiveReason,
61:             message: SESSION_ENDED_COPY[effectiveReason],
62:           });
63:           // Retain until the page has actually received it; a throwing publish leaves this for retry.
64:           retained = { meta, event };
65:           seams.publish(event);
66:           retained = null;
67:         }
68:         return meta;
69:       })();
70:       inFlight = run.finally(() => {
71:         inFlight = null;
72:       });
73:       return inFlight;
74:     },
75:     active() {
76:       return inFlight !== null;
77:     },
78:   };
79: }

