1: // What: exposes local report building, progress, and cancellation over IPC.
2: // Why: the engine and stored session files stay in main; the renderer receives only validated results.
3: // Removed: the Report screen could not request a real report, see progress, or stop one.
4: import {
5:   reportCancelResultSchema,
6:   reportProgressSchema,
7:   reportResultSchema,
8: } from '../shared/contracts.js';
9: import { EVENT_CHANNELS } from '../shared/channels.js';
10: import { AppError } from '../shared/errors.js';
11: import { registerInvokeChannel } from './ipc-registry.js';
12: import { buildReport } from './report.js';
13: import { withReportExclusion } from './report-lock.js';
14: import { defaultDataRoot } from './store.js';
15: 
16: interface ActiveBuild {
17:   controller: AbortController;
18:   /** Once true, the artifact commit has begun and a cancel request must not be acknowledged. */
19:   committing: boolean;
20: }
21: 
22: /** One active build per session. */
23: const activeBuilds = new Map<string, ActiveBuild>();
24: 
25: export function registerReportHandler(dataRoot: () => string = defaultDataRoot): void {
26:   registerInvokeChannel('reportBuild', async (event, payload) => {
27:     const { sessionId, pgns } = payload;
28:     if (activeBuilds.has(sessionId)) throw new AppError('session_busy');
29:     const build: ActiveBuild = { controller: new AbortController(), committing: false };
30:     activeBuilds.set(sessionId, build);
31:     try {
32:       // Shared exclusion also covers insight artifact reads; only one Stockfish build runs at once.
33:       const result = await withReportExclusion(() =>
34:         buildReport(dataRoot(), sessionId, pgns, undefined, {
35:           signal: build.controller.signal,
36:           onCommitStart: () => {
37:             build.committing = true;
38:           },
39:           onProgress: (progress) => {
40:             if (event.sender.isDestroyed()) return;
41:             const message = reportProgressSchema.safeParse({ sessionId, ...progress });
42:             if (message.success) event.sender.send(EVENT_CHANNELS.reportProgress, message.data);
43:           },
44:         }),
45:       );
46:       return reportResultSchema.parse(result);
47:     } finally {
48:       if (activeBuilds.get(sessionId) === build) activeBuilds.delete(sessionId);
49:     }
50:   });
51: 
52:   registerInvokeChannel('reportCancel', (_event, payload) => {
53:     const build = activeBuilds.get(payload.sessionId);
54:     if (!build) return reportCancelResultSchema.parse({ cancelled: false });
55:     // A commit already in progress is not cancellable; acknowledging it would lie about the artifact.
56:     if (build.committing) return reportCancelResultSchema.parse({ cancelled: false });
57:     build.controller.abort();
58:     return reportCancelResultSchema.parse({ cancelled: true });
59:   });
60: }

