5: import { engineCalibrationNote, engineFailureNote } from '../shared/timeline';
6: 
7: export function VerdictLine({ report }: { report: Report }) {
8:   const baseline = formatNumber(report.baselineBpm);
9:   const coverage = Math.round(report.coveragePct);
10:   const threshold = formatNumber(report.timeline.elevatedThresholdBpm);
11:   const engineNote = engineFailureNote(report.engine);
12: 
13:   return (
14:     <section className="verdict-section" aria-label="Session verdict">
15:       <p className="verdict-meta">
16:         Baseline {baseline} bpm · Elevated ≥ {threshold} bpm · Coverage {coverage}%
17:       </p>
18:       <h1 className="verdict-line">{report.verdict}</h1>
19:       <p className="verdict-note verdict-engine">{engineCalibrationNote(report.engine)}</p>
20:       {engineNote ? <p className="verdict-note">{engineNote}</p> : null}
21:     </section>
22:   );
23: }
24: 
25: function formatNumber(value: number): string {
26:   return Number.isInteger(value) ? String(value) : value.toFixed(1);
27: }

