11: import { logError } from './log.js';
12: 
13: export type IpcHandler = (event: IpcMainInvokeEvent, payload: unknown) => unknown | Promise<unknown>;
14: export type UnexpectedReporter = (channel: string, error: unknown) => void;
15: 
16: function reportUnexpected(channel: string, error: unknown): void {
17:   const detail = error instanceof Error ? error.message : 'unknown error';
18:   logError(`[chesspulse] ${channel} failed: ${detail}`);
19: }
20: 
21: /**
22:  * Registers nothing and imports no Electron runtime, so the contract is testable in plain Node.
23:  * An AppError is passed through; anything else is reduced to `fallback` and logged on this side.
24:  */
25: export function guardIpcHandler(
26:   channel: string,
27:   handler: IpcHandler,
28:   fallback: AppErrorCode = 'internal',
29:   report: UnexpectedReporter = reportUnexpected,
30: ): (event: IpcMainInvokeEvent, payload: unknown) => Promise<unknown> {
