// What: the small display rules for a stored session row.
// Why: Home and Sessions must describe date, duration, coverage, and report presence the same way.
// Removed: each list would format the same fields differently, and a null would print as a number.
import { formatElapsedMs } from './sensing.js';

export function formatSessionDate(epochMs: number): string {
  if (!Number.isFinite(epochMs)) return 'Unknown date';
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  }).format(new Date(epochMs));
}

export function formatSessionDuration(ms: number | null): string {
  return ms === null ? 'No duration' : `${formatElapsedMs(ms)} elapsed`;
}

export function coverageLabel(pct: number | null): string {
  return pct === null ? 'No coverage' : `${Math.round(pct)}% coverage`;
}

export function reportPresenceLabel(hasReport: boolean): string {
  return hasReport ? 'Report ready' : 'No report yet';
}

import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import {
  coverageLabel,
  formatSessionDate,
  formatSessionDuration,
  reportPresenceLabel,
} from './session-list.js';

describe('session row labels', () => {
  it('formats duration and treats a missing duration honestly', () => {
    assert.equal(formatSessionDuration(65_000), '1:05 elapsed');
    assert.equal(formatSessionDuration(null), 'No duration');
  });

  it('formats coverage and treats a missing value honestly', () => {
    assert.equal(coverageLabel(75.4), '75% coverage');
    assert.equal(coverageLabel(0), '0% coverage');
    assert.equal(coverageLabel(null), 'No coverage');
  });

  it('names report presence without guessing', () => {
    assert.equal(reportPresenceLabel(true), 'Report ready');
    assert.equal(reportPresenceLabel(false), 'No report yet');
  });

  it('formats a real date and refuses a non-finite one', () => {
    const first = formatSessionDate(1_700_000_000_000);
    const second = formatSessionDate(1_700_003_600_000);
    assert.ok(first.length > 0);
    assert.notEqual(first, second);
    assert.equal(formatSessionDate(Number.NaN), 'Unknown date');
  });
});

